INSERT INTO `claims` VALUES (9,'FI-006',2,'กระเป๋าใบนี้น่าจะเป็นของผมครับ เป็น Anello สีดำ ข้างในมีสมุดฟิสิกส์และไม้บรรทัดสามเหลี่ยม','0812345678 / @sarawut','approved','2026-10-16 17:00:00'),(10,'FI-007',6,'iPhone สีขาวเคสใสน่าจะเป็นของหนูค่ะ มีรูปวอลเปเปอร์เป็นแมวสีส้ม','0898765432 / @vava_uni','approved','2026-10-17 11:30:00'),(11,'FI-008',2,'แว่นตาอาจเป็นของผมครับ เป็นกรอบสีทอง เลนส์สายตา -2.50 ทั้งสองข้าง','0812345678','pending','2026-10-18 14:00:00'),(12,'FI-010',6,'สร้อยคอน่าจะเป็นของหนูค่ะ มีจี้รูปดาวห้อยอยู่ด้วย','0898765432 / @vava_uni','pending','2026-10-19 08:00:00');
