INSERT INTO `clues` VALUES (9,'FI-001',6,'เห็นกระเป๋าสตางค์สีน้ำตาลอยู่ที่โต๊ะประจำหน้าห้องเรียน 301 ตอนประมาณบ่ายสองโมง','0898765432','2026-10-15 14:00:00'),(10,'FI-002',8,'มีนักศึกษาส่งหูฟังมาให้ที่เคาน์เตอร์ประชาสัมพันธ์แล้ว กรุณามาติดต่อรับได้เลย','0899999999 / @founditadmin','2026-10-16 13:30:00'),(11,'FI-003',2,'เห็นกุญแจที่มีพวงกุญแจหมีอยู่ที่บอร์ดประชาสัมพันธ์ลานจอดรถครับ','0812345678','2026-10-17 09:00:00'),(12,'FI-1000',10,'ผมพบแล้ว','099999999','2026-10-19 22:58:23');
