CREATE TABLE `items` (
  `id` varchar(20) NOT NULL,
  `user_id` int(11) DEFAULT NULL,
  `type` enum('lost','found') NOT NULL,
  `title` varchar(150) NOT NULL,
  `category` varchar(50) NOT NULL,
  `color` varchar(50) NOT NULL,
  `location` varchar(100) NOT NULL,
  `event_date` date NOT NULL,
  `status` enum('searching','found','returned') NOT NULL DEFAULT 'searching',
  `returned_at` datetime DEFAULT NULL,
  `description` text NOT NULL,
  `image` mediumtext DEFAULT NULL,
  `contact_name` varchar(100) DEFAULT NULL,
  `contact_phone` varchar(30) DEFAULT NULL,
  `contact_line` varchar(100) DEFAULT NULL,
  `contact_facebook` varchar(200) DEFAULT NULL,
  `contact_instagram` varchar(100) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_type` (`type`),
  KEY `idx_category` (`category`),
  KEY `idx_color` (`color`),
  KEY `idx_location` (`location`),
  KEY `idx_event_date` (`event_date`),
  KEY `idx_status` (`status`),
  KEY `fk_items_user` (`user_id`),
  CONSTRAINT `fk_items_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
