INSERT INTO `items` VALUES ('FI-001',2,'lost','กระเป๋าสตางค์หนังสีน้ำตาล','กระเป๋า','น้ำตาล','อาคารเรียน','2026-10-15','searching',NULL,'กระเป๋าสตางค์หนังสีน้ำตาล ภายในมีบัตรนักศึกษา บัตรประชาชน และเงินสดประมาณ 500 บาท หายไประหว่างนั่งเรียนในชั้น 3','data:image/jpeg;base64,','สราวุฒิ พรมโคตร','0812345678','@sarawut',NULL,NULL,'2026-10-15 09:30:00','2026-10-19 20:01:14'),('FI-002',2,'lost','หูฟัง Sony สีเทา','อิเล็กทรอนิกส์','เทา','โรงอาหาร','2026-10-16','searching',NULL,'หูฟัง Sony ไร้สาย สีเทา ตัดเสียงรบกวน ลืมไว้บนโต๊ะโรงอาหารช่วงพักกลางวัน','data:image/jpeg;base64,','สราวุฒิ พรมโคตร','0812345678','@sarawut',NULL,NULL,'2026-10-16 12:45:00','2026-10-19 19:54:47'),('FI-003',6,'lost','กุญแจรถมอเตอร์ไซค์พร้อมพวงกุญแจรูปหมี','กุญแจ','ชมพู','ลานจอดรถ','2026-10-17','searching',NULL,'กุญแจมอเตอร์ไซค์ Honda พร้อมพวงกุญแจหมูสีชมพูเล็กๆ หายไประหว่างจอดรถช่วงเช้า','data:image/jpeg;base64,','วาวา','0898765432','@vava_uni',NULL,NULL,'2026-10-17 08:15:00','2026-10-19 19:51:20'),('FI-004',6,'lost','ร่มสีฟ้าลายขาว','ของใช้','ฟ้า','ห้องสมุด','2026-10-18','searching',NULL,'ร่มพับสีฟ้าลาย Doraemon ลืมไว้ที่ชั้นวางร่มหน้าห้องสมุด เมื่อวานตอนเย็น','data:image/jpeg;base64,','วาวา','0898765432','@vava_uni',NULL,NULL,'2026-10-18 18:00:00','2026-10-19 19:47:37'),('FI-005',2,'lost','นาฬิกา Casio G-Shock สีดำ','อิเล็กทรอนิกส์','ดำ','โรงอาหาร','2026-10-14','found',NULL,'นาฬิกา G-Shock สีดำ','data:image/jpeg;base64,','สราวุฒิ พรมโคตร','0812345678','@sarawut',NULL,NULL,'2026-10-14 14:20:00','2026-10-19 20:03:07'),('FI-006',6,'found','พบกระเป๋านักศึกษาสีดำ','กระเป๋า','ดำ','ห้องสมุด','2026-10-16','found',NULL,'พบกระเป๋าเป้สีดำ ลืมไว้บนโต๊ะหลังเลิกเรียน ภายในมีสมุด ปากกา และอุปกรณ์การเรียน','data:image/jpeg;base64,','วาวา','0898765432','@vava_uni',NULL,NULL,'2026-10-16 16:30:00','2026-10-19 19:52:56'),('FI-007',8,'found','พบโทรศัพท์มือถือ iPhone สีขาว','อิเล็กทรอนิกส์','ขาว','อาคารกิจกรรมนักศึกษา','2026-10-17','returned','2026-10-19 19:49:07','พบ iPhone สีขาว เคสใสบนม้านั่งหน้าอาคารสำนักงาน ล็อกหน้าจออยู่ เก็บรักษาไว้ที่เคาน์เตอร์ประชาสัมพันธ์','data:image/jpeg;base64,','ผู้ดูแลระบบ','0899999999','@founditadmin',NULL,NULL,'2026-10-17 10:00:00','2026-10-19 19:49:07'),('FI-008',6,'found','พบแว่นตากรอบสีทอง','เสื้อผ้าและเครื่องประดับ','ทอง','โรงอาหาร','2026-10-18','found',NULL,'พบแว่นตากรอบสีทอง วางอยู่บนโต๊ะโรงอาหารหลังทุกคนลุกไปแล้ว เก็บไว้รอเจ้าของมารับ','data:image/jpeg;base64,','วาวา','0898765432','@vava_uni',NULL,NULL,'2026-10-18 13:20:00','2026-10-19 19:56:26'),('FI-009',8,'found','บัตรนักศึกษา','บัตร','น้ำเงิน','อาคารกิจกรรมนักศึกษา','2026-10-15','returned','2026-10-19 19:58:05','พบบัตรนักศึกษาหน้าลานกิจกรรม ส่งให้งานทะเบียนเรียบร้อยแล้ว หากเป็นเจ้าของกรุณาติดต่อสำนักทะเบียน','data:image/jpeg;base64,','ผู้ดูแลระบบ','0899999999','@founditadmin',NULL,NULL,'2026-10-15 14:00:00','2026-10-19 19:58:05'),('FI-010',2,'found','พบสร้อยคอทองคำขาว','เสื้อผ้าและเครื่องประดับ','ขาว','สนามกีฬา','2026-09-19','returned','2026-10-19 20:04:16','พบสร้อยคอทองคำขาวบนอ่างล้างมือ ห้องน้ำหญิงอาคาร A ชั้น 2 เก็บรักษาไว้อย่างดี รอเจ้าของมาติดต่อ','data:image/jpeg;base64,','สราวุฒิ พรมโคตร','0812345678','@sarawut',NULL,NULL,'2026-10-19 07:30:00','2026-10-19 20:04:16'),('FI-1000',9,'lost','กระเป๋า Hermes สีเขียว','กระเป๋า','เขียว','หอพักนักศึกษา','2026-10-19','returned','2026-10-19 23:01:07','Hermes หนังจระเข้','data:image/jpeg;base64,','Jirameth Juikumjorn','0926776776','jui6767','jirameth','Jirameth','2026-10-19 22:46:27','2026-10-19 23:01:07'),('FI-999',8,'found','พบสมุดโน้ตสีน้ำตาล (ตัวอย่างคืนของเกิน 30 วัน)','เครื่องเขียน','น้ำตาล','ห้องสมุด','2026-08-01','returned','2026-08-10 10:00:00','ส่งคืนเจ้าของแล้วตั้งแต่เดือนสิงหาคม',NULL,'ผู้ดูแลระบบ','0899999999','@founditadmin',NULL,NULL,'2026-08-01 09:00:00','2026-10-19 16:58:37');
